const tls = require('tls');
const dns = require('dns').promises;
const net = require('net');
const BLOCKED = /^(localhost|.*\.local|.*\.internal|.*\.lan)$/i;

function isPublicIp(ip) {
  const family = net.isIP(ip);
  if (family === 4) {
    const [a,b,c] = ip.split('.').map(Number);
    if (a === 0 || a === 10 || a === 127 || a >= 224) return false;
    if (a === 100 && b >= 64 && b <= 127) return false;
    if (a === 169 && b === 254) return false;
    if (a === 172 && b >= 16 && b <= 31) return false;
    if (a === 192 && (b === 168 || (b === 0 && c === 0) || (b === 0 && c === 2))) return false;
    if (a === 198 && (b === 18 || b === 19 || (b === 51 && c === 100))) return false;
    if (a === 203 && b === 0 && c === 113) return false;
    return true;
  }
  if (family === 6) {
    const normalized = ip.toLowerCase();
    if (normalized.startsWith('2001:db8:') || normalized.startsWith('2001:0:') || normalized.startsWith('2002:')) return false;
    const firstWord = parseInt(normalized.split(':')[0] || '0', 16);
    // Permit only global-unicast 2000::/3. This excludes unspecified, loopback,
    // IPv4-mapped, unique-local, link-local, multicast and other special ranges.
    return (firstWord & 0xe000) === 0x2000;
  }
  return false;
}

function probe(host, port, address) {
  return new Promise(resolve => {
    const options = {
      host: address.address,
      port,
      rejectUnauthorized: false,
      ...(net.isIP(host) ? {} : { servername: host })
    };
    const sock = tls.connect(options, () => {
      const cert = sock.getPeerCertificate();
      sock.end();
      resolve({ ok: !!(cert && cert.valid_to), cert });
    });
    sock.setTimeout(10000, () => { sock.destroy(); resolve({ ok: false, error: 'timeout' }); });
    sock.on('error', error => resolve({ ok: false, error: error.message }));
  });
}

const items = $input.all();
const out = [];
const stats = { total: items.length, checked: 0, failed: 0, blocked: 0, findings: 0 };

for (let i = 0; i < items.length; i += 5) {
  const chunk = items.slice(i, i + 5);
  const results = await Promise.all(chunk.map(async item => {
    const vendor = item.json;
    let host, port;
    try {
      const url = new URL(/^https?:\/\//i.test(vendor.website) ? vendor.website : 'https://' + vendor.website);
      host = url.hostname.replace(/^\[|\]$/g, '').toLowerCase();
      port = Number(url.port) || 443;
    } catch {
      return { vendor, error: 'invalid_url' };
    }
    if (BLOCKED.test(host)) return { vendor, host, error: 'blocked_host' };
    try {
      const addresses = await dns.lookup(host, { all: true, verbatim: true });
      // Reject the entire hostname if any answer is private/reserved. Connect only
      // to an address already checked, avoiding a second DNS lookup at connect time.
      if (!addresses.length || addresses.some(entry => !isPublicIp(entry.address))) {
        return { vendor, host, error: 'blocked_address' };
      }
      const selected = addresses.find(entry => entry.family === 4) || addresses[0];
      return { vendor, host, port, ...(await probe(host, port, selected)) };
    } catch (error) {
      return { vendor, host, error: error.message || 'dns_or_tls_error' };
    }
  }));

  for (const result of results) {
    if (result.error === 'blocked_host' || result.error === 'blocked_address') {
      stats.blocked++;
      continue;
    }
    if (!result.ok) { stats.failed++; continue; }
    stats.checked++;
    const notAfter = new Date(result.cert.valid_to);
    const daysLeft = Math.floor((notAfter - Date.now()) / 86400000);
    const severity = daysLeft < 7 ? 'critical' : daysLeft < 30 ? 'high' : daysLeft < 60 ? 'medium' : null;
    if (!severity) continue;
    const issuer = (result.cert.issuer && (result.cert.issuer.O || result.cert.issuer.CN)) || 'n/a';
    stats.findings++;
    out.push({ json: {
      kind: 'finding', vendor_id: result.vendor.id, source: 'tls_expiry',
      source_ref: 'tls:' + result.host + ':' + result.port + ':' + notAfter.toISOString().slice(0, 10) + ':' + severity,
      title: daysLeft < 0 ? 'Certificado TLS EXPIRADO (' + result.host + ')'
                          : 'Certificado TLS expira en ' + daysLeft + ' días (' + result.host + ')',
      description: 'Emisor: ' + issuer + ' · Válido hasta ' + notAfter.toISOString(),
      severity,
      evidence: { host: result.host, port: result.port, days_left: daysLeft, issuer, not_after: notAfter.toISOString(),
                  subject: result.cert.subject && result.cert.subject.CN }
    }});
  }
}
out.push({ json: { kind: 'summary', job_type: 'tls_expiry', interval_min: 1440,
  status: stats.checked === 0 && stats.total > 0 ? 'error' : (stats.failed > 0 ? 'partial' : 'ok'),
  meta: stats } });
return out;
